from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            touches_edge = False
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                touches_edge |= x == 0 or x == h - 1 or y == 0 or y == w - 1
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == bg and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if not touches_edge:
                for x, y in comp:
                    out[x][y] = 4
    # Extend a filled cavity to a diagonally-adjacent background notch when
    # that notch is the sole one-cell corner opening into the exterior.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or out[r][c] != bg:
                continue
            if any(out[nr][nc] == 4 for nr in range(max(0, r - 1), min(h, r + 2))
                   for nc in range(max(0, c - 1), min(w, c + 2))):
                # only bridge when the cell is bounded on two orthogonal sides
                orth = [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)]
                walls = sum(1 for nr, nc in orth if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != bg)
                if walls >= 2:
                    out[r][c] = 4
    return out
